450:     let options: { label: string; description: string }[] = [];
451: 
452:     switch (encounterModality) {
453:       case 'LanguageReflective':
454:         narrativeIntro = `${holonName} sits across from you, their gaze steady. The firelight casts long shadows. They speak:`;
455:         questionText = fallback.prompt ?? 'What moved you to act?';
456:         options = [
457:           { label: 'Reflect deeply', description: 'Consider the question from multiple angles' },
458:           { label: 'Respond instinctively', description: 'Trust your first impulse' },
459:           { label: 'Sit with it', description: 'Allow the question to remain open' },
460:           { label: 'Challenge the premise', description: 'Question the foundation of what was asked' },
461:         ];
462:         break;
463:       case 'ScenarioChoice':
464:         narrativeIntro = `${holonName} confronts you. The air is tense. A choice must be made.`;
465:         questionText = fallback.scenario ?? 'A crossroads appears. Each path carries weight.';
466:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
467:         break;
468:       case 'Strategic':
469:         narrativeIntro = `The war-table is spread before you. ${holonName} surveys the terrain. Three routes. Limited forces.`;
470:         questionText = fallback.scenario ?? fallback.prompt ?? 'Resources are limited. The map shows three routes to the objective.';
471:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
472:         break;
473:       case 'Embodied':
474:         narrativeIntro = `The war-drums begin. ${holonName} guides you. Your body knows this rhythm.`;
475:         questionText = fallback.prompt ?? 'Close your eyes. Where do you feel tension in your body right now?';
476:         options = [
477:           { label: 'Follow the rhythm', description: 'Let the drum guide your body' },
478:           { label: 'Resist the beat', description: 'Fight against the pull' },
479:           { label: 'Breathe into it', description: 'Allow the sensation to move through you' },
480:           { label: 'Still yourself', description: 'Find the stillness within the movement' },
481:         ];
482:         break;
483:       case 'SocialCooperative':
484:         narrativeIntro = `${holonName} looks to you. Others wait for direction. The group needs your word.`;
485:         questionText = fallback.scenario ?? 'The scouts look to you. The path splits — one leads through danger, the other through uncertainty.';
486:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
487:         break;
488:       case 'ImmersiveRPG':
489:         narrativeIntro = `The world stretches before you. ${holonName} appears — ${holonRole} of this domain. What calls?`;
490:         questionText = fallback.prompt ?? 'The world stretches before you. A path winds through unfamiliar terrain. Something waits ahead.';
491:         options = [
492:           { label: 'Press forward', description: 'Step into the unknown' },
493:           { label: 'Survey the area', description: 'Gather information first' },
494:           { label: 'Seek shelter', description: 'Find safety before advancing' },
495:           { label: 'Call out', description: 'Announce your presence' },
496:         ];
497:         break;
498:       default:
499:         narrativeIntro = `${holonName} presents a challenge. The moment demands clarity.`;
500:         questionText = fallback.prompt ?? fallback.framing ?? 'Focus. The moment demands clarity.';
501:         options = [
502:           { label: 'Engage', description: 'Step into the challenge' },
503:           { label: 'Reflect', description: 'Consider before acting' },
504:           { label: 'Withdraw', description: 'Step back and reassess' },
505:           { label: 'Negotiate', description: 'Seek a middle path forward' },
506:         ];
507:         break;
508:     }
509: 
510:     const defaultOpts = [
511:       { label: 'Act decisively', description: 'Take the direct approach' },
512:       { label: 'Observe first', description: 'Gather more information' },
513:       { label: 'Seek alliance', description: 'Find strength in others' },
514:       { label: 'Deceive and maneuver', description: 'Use misdirection to your advantage' },
515:     ];
516:     while (options.length < 4) {
517:       const extra = defaultOpts[options.length];
518:       if (extra) options.push(extra);
519:       else break;
520:     }
521: 
522:     const fullPrompt = `${narrativeIntro}\n\n${questionText}`;
523: 
524:     const askParams: AskUserQuestionParams = {
525:       questions: [{
526:         question: fullPrompt,
527:         header: encounterModality,
528:         options,
529:         allowWriteIn: true,
530:         multiSelect: false,
531:       }],
532:     };
533: 
534:     const result = await this.uiHandler.askUser(askParams);
535:     const answer = result.answers[0];
536:     const narrativeSummary = answer?.writeInValue ?? (answer?.selectedLabels[0] ?? 'The player engaged with the encounter.');
537: 
538:     const evaluated = this.evaluateFallbackResponse(narrativeSummary);
539: 
540:     const fallbackParams = {
541:       passed: evaluated.passed,
542:       feedback: evaluated.feedback,
543:       polarityDirection: evaluated.polarityDirection,
544:       driveScores: evaluated.driveScores,
545:       driveSignals: evaluated.driveSignals,
546:       narrativeSummary: typeof narrativeSummary === 'string' ? narrativeSummary : 'The player engaged with the encounter.',
547:     };
548: 
549:     const finalResult = this.createAssessmentResult(evaluated.passed, {}, evaluated.driveScores);
550:     const outcome = this.finalizeEncounter(fallbackParams, now);
551: 
552:     return {
553:       ...outcome,
554:       finalResult,
555:       messages: this.messages,
556:     };
557:   }
