559:   /**
560:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
561:    * and scoring rubric to present a real developmental assessment even without the LLM.
562:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
563:    * evaluates the response against drive probes, detects shadow patterns,
564:    * and computes altitude progression.
565:    */
566:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
567:     const module = this.module!;
568:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
569:     const holonName = holon?.name ?? 'A presence';
570:     const currentModality = this.encounter.modality;
571: 
572:     // 1. Select the best task from the module based on modality
573:     const task = this.selectTaskForModality(module, currentModality);
574:     // Track the actual presented task for narrative building (fix B.2)
575:     this._currentPresentedTask = task;
576: 
577:     // 2. Present the task as a narrative challenge via uiHandler
578:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
579:     const answer = askResult.answers[0];
580:     const rawLabel = answer?.selectedLabels[0] ?? '';
581:     const writeIn = answer?.writeInValue;
582:     const playerResponseText = writeIn ?? rawLabel;
583: 
584:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
585:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
586:     const endTimeMs = Date.now();
587:     let evaluation: {
588:       passed: boolean;
589:       polarityDirection: 'sto' | 'sts' | 'neutral';
590:       driveScores: { agency: number; communion: number; eros: number; agape: number };
591:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
592:       feedback: string;
593:     };
594:     let trialResult: TrialResult | null = null;
595: 
596:     if (this._currentRendererEvaluate) {
597:       // Use the TaskRenderer's evaluate function for real scoring
598:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
599: 
600:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
601:       const rawResp = trialResult?.rawResponse as any;
602:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
603:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
604:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
605: 
606:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
607:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
608: 
609:       // D.9: Use shared shadow keyword detection helper (DRY)
610:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
611:       if (writeIn) {
612:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
613:       }
614: 
615:       // When a write-in is present, its keyword-based detection takes priority over
616:       // the renderer's label matching (which can false-positive on short words like 'I').
617:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
618:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
619: 
620:       // Build differentiated drive scores:
621:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
622:       // - Other drives get baseline neutral (0.5)
623:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
624:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
625: 
626:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
627:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
628:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
629:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
630:       const rubricWeights = module.scoringRubric.dimensionWeights;
631:       const trialDims = trialResult!.dimensions;
632:       let weightedSum = 0;
633:       let totalWeight = 0;
634:       for (const [dim, weight] of Object.entries(rubricWeights)) {
635:         const val = trialDims[dim as keyof typeof trialDims];
636:         if (weight && typeof val === 'number') {
637:           weightedSum += val * weight;
638:           totalWeight += weight;
639:         }
640:       }
641:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
642:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
643:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
644: 
645:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
646:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
647:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
648:       const driveScores = {
649:         agency: effectiveDrive === 'agency' ? matchedScore
650:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
651:           : matchedScore,
652:         communion: effectiveDrive === 'communion' ? matchedScore
653:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
654:           : matchedScore,
655:         eros: effectiveDrive === 'eros' ? matchedScore
656:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
657:           : matchedScore,
658:         agape: effectiveDrive === 'agape' ? matchedScore
659:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
660:           : matchedScore,
661:       };
662: 
663:       // Determine polarity from the effective drive detection
664:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
665:         : effectivePolarity === 'sto' ? 'sto' as const
666:         : 'neutral' as const;
667: 
668:       // Derive drive signals from the expression pattern.
669:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
670:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
671:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
672:       const driveSignals = {
673:         agency: effectiveDrive === 'agency'
674:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
675:           : 'HealthyBalanced',
676:         communion: effectiveDrive === 'communion'
677:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
678:           : 'HealthyBalanced',
679:         eros: effectiveDrive === 'eros'
680:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
681:           : 'HealthyBalanced',
682:         agape: effectiveDrive === 'agape'
683:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
684:           : 'HealthyBalanced',
685:       };
686: 
687:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
688:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
689:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
690:       const hasShadow = !!shadowFromWriteIn;
691:       const passed = !hasShadow && effectiveScore >= passThreshold;
692: 
693:       // Build contextual developmental feedback based on score, drive, polarity, and history
694:       const driveLabel = effectiveDrive ?? 'unidentified';
695:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
696:       const scorePct = (baseScore * 100).toFixed(0);
697:       const historyCount = this.history.length;
698:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
699:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
700:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
701:         : '';
702: 
703:       const feedback = hasShadow
704:         ? `A ${shadowFromWriteIn} pattern surfaced through your ${driveLabel} expression (${polarityLabel}). In the developmental framework, this shadow arises when the ${driveLabel} drive becomes imbalanced — either clinging to lower patterns (dark) or bypassing toward higher without integration (golden). Naming it here is the first step toward healing it. ${historyCount > 0 ? `This is your ${historyCount + 1}th encounter — each shadow surfaced is an opportunity for the field to work with you.` : ''}`
705:         : passed
706:           ? `Your ${driveLabel} drive expressed with health (performance: ${scorePct}%, polarity: ${polarityLabel}). ${parseInt(scorePct) >= 80 ? 'Strong performance — the integration is deepening across the ' + module.line.toLowerCase() + ' dimension.' : 'Solid engagement — the ' + module.line.toLowerCase() + ' capacity at ' + module.stage + ' stage is growing.'} ${consistencyNote}The field recognizes your sustained attention to this developmental edge.`
707:           : `Your ${driveLabel} drive expressed at ${scorePct}% performance (${polarityLabel}). ${parseInt(scorePct) >= 40 ? 'Close to the threshold — the gap between where you are and where this capacity can be is narrowing. A focused effort on the next encounter may tip the balance.' : 'This is a genuine edge for you. The ' + module.line.toLowerCase() + ' line at ' + module.stage + ' stage is where your developmental work lives right now — not as punishment, but as invitation.'} The ${module.line.toLowerCase()} dimension will continue to offer opportunities to strengthen this capacity.`;
708: 
709:       evaluation = {
710:         passed,
711:         polarityDirection,
712:         driveScores,
713:         driveSignals,
714:         feedback,
715:       };
716:     } else {
717:       // Fallback: keyword-based evaluation
718:       evaluation = this.evaluateViaDriveProbes(module, playerResponseText);
719:     }
720: 
721:     // 4. Detect shadow surfacing from response pattern (with optional forceShadow override)
722:     const validQuadrants = ['DarkAddiction', 'DarkAllergy', 'GoldenAddiction', 'GoldenAllergy'] as const;
723:     const forcedQuadrant = this.forceShadow && validQuadrants.includes(this.forceShadow as any)
724:       ? this.forceShadow as ShadowQuadrant
725:       : null;
726:     // Shadow detection only fires for write-in text (free-form responses)
727:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
728:     const isWriteIn = !!writeIn;
729:     const shadowSignal = forcedQuadrant
730:       ? { quadrant: forcedQuadrant, intensity: 0.7 }
731:       : this.detectShadowFromResponse(playerResponseText, currentModality, isWriteIn);
732: 
733:     // If forceShadow is active, propagate to drive signals AND force-fail the encounter
734:     if (forcedQuadrant && this._currentRendererEvaluate) {
735:       const forcedDrive = forcedQuadrant === 'DarkAddiction' ? 'agency'
736:         : forcedQuadrant === 'DarkAllergy' ? 'communion'
737:         : forcedQuadrant === 'GoldenAddiction' ? 'eros'
738:         : 'agape';
739:       const forcedSignal = forcedQuadrant;
740:       evaluation.driveSignals = { ...evaluation.driveSignals, [forcedDrive]: forcedSignal } as typeof evaluation.driveSignals;
741:       // Forced shadow = pathology detected → must fail
742:       evaluation = { ...evaluation, passed: false, feedback: `Shadow surfaced: ${forcedQuadrant} through ${forcedDrive} expression (forced). This indicates the ${forcedDrive} drive is operating from a developmental shadow — awareness of this pattern is the first step toward integration.` };
743:     }
744: 
745:     // 5. Build a rich narrative summary from the module context
746:     // Pass the actual presented task so narrative matches what the user saw
747:     const narrativeSummary = this.buildModuleNarrative(module, playerResponseText, evaluation.passed, currentModality, holonName, task);
748: 
749:     // 6. Check for altitude shift: only when ALL drives HealthyBalanced AND passed
750:     const altitudeShift = this.computeAltitudeShift(evaluation.driveSignals, module, stage, evaluation.passed);
751: 
752:     const finalResult = this.createAssessmentResult(
753:       evaluation.passed, {}, evaluation.driveScores, trialResult ? [trialResult] : undefined,
754:     );
755: 
756:     // Build outcome with altitude shift support
757:     const energeticDirection: EnergeticDirection = evaluation.polarityDirection === 'sto' ? 'Radiative'
758:       : evaluation.polarityDirection === 'sts' ? 'Absorptive' : 'Diffuse';
759: 
760:     const SIGNAL_MAP: Record<string, DriveDirectionality> = {
761:       'HealthyBalanced': 'HealthyBalanced',
762:       'DarkAddicted': 'DarkAddicted',
763:       'DarkAverted': 'DarkAverted',
764:       'GoldenAddicted': 'GoldenAddicted',
765:       'GoldenAverted': 'GoldenAverted',
766:     };
767: 
768:     const baseDir: DriveDirectionality = evaluation.passed ? 'HealthyBalanced' : 'DarkAddicted';
769:     const driveDirectionality: Record<Drive, DriveDirectionality> = {
770:       Agency: SIGNAL_MAP[evaluation.driveSignals.agency] ?? baseDir,
771:       Communion: SIGNAL_MAP[evaluation.driveSignals.communion] ?? baseDir,
772:       Eros: SIGNAL_MAP[evaluation.driveSignals.eros] ?? baseDir,
773:       Agape: SIGNAL_MAP[evaluation.driveSignals.agape] ?? baseDir,
774:     };
775: 
776:     const response: PlayerResponse = {
777:       encounterId: this.encounter.id,
778:       energeticDirection,
779:       driveDirectionality: driveDirectionality as Record<Drive, DriveDirectionality>,
780:       stageOrientation: evaluation.polarityDirection === 'sto' ? 'ReachingHigher' : 'Homeostatic',
781:       sourceOfNourishment: evaluation.polarityDirection === 'sto' ? 'HigherRealm'
782:         : (evaluation.polarityDirection === 'sts' ? 'LowerRealm' : 'Ambivalent'),
783:       shadowSurfaced: shadowSignal?.quadrant ?? null,
784:       shadowResolvedId: null,
785:       narrativeSummary,
786:     };
787: 
788:     const record = processOutcome(this.encounter, response, now);
789: 
790:     // Override altitudeShift on the record if computed
791:     const updatedRecord: ConsequenceRecord = {
792:       ...record,
793:       altitudeShift: altitudeShift ?? null,
794:     };
795: 
796:     // Apply failure consequences: accelerate theta-decay for failed modules
797:     if (!evaluation.passed) {
798:       const [fl, fs] = this.encounter.moduleRef.split(':');
799:       const cellKey = `${fl}:${fs}`;
800:       const currentTs = this.significator.theta.lastEncounter[cellKey] ?? 0;
801:       if (currentTs > now - 3600000) {
802:         (this.significator.theta.lastEncounter as Record<string, number>)[cellKey] = now - 7200000;
803:       }
804:     }
805: 
806:     // Apply consequences — shadow entries will be created if shadowSurfaced is set
807:     const updated = applyConsequences(this.significator, this.world, updatedRecord, this.encounter);
808: 
809:     // Apply altitude shift if computed
810:     let finalSig = updated.sig;
811:     if (altitudeShift) {
812:       const currentOrd = stageOrdinal(altitudeShift.to);
813:       const ALL_STAGES: readonly Stage[] = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'];
814:       if (currentOrd < ALL_STAGES.length - 1) {
815:         const nextStage = ALL_STAGES[currentOrd + 1]!;
816:         finalSig = {
817:           ...finalSig,
818:           altitudes: { ...finalSig.altitudes, [altitudeShift.line]: nextStage },
819:         };
820:         // Update currentStage if all lines are at least at nextStage
821:         const allAtNext = Object.values(finalSig.altitudes).every(
822:           a => stageOrdinal(a) >= stageOrdinal(nextStage),
823:         );
824:         if (allAtNext) {
825:           finalSig = { ...finalSig, currentStage: nextStage };
826:         }
827:       }
828:     }
829: 
830:     // PESTLE accumulation
831:     const PESTLE_DIMS_ARRAY: (keyof PESTLETension)[] = ['political', 'economic', 'social', 'technological', 'legal', 'environmental'];
832:     const dim = PESTLE_DIMS_ARRAY[Math.floor(Math.random() * PESTLE_DIMS_ARRAY.length)]!;
833:     const newTension = accumulateTension(
834:       (updated.world as any).pestleTension ?? { political: 0, economic: 0, social: 0, technological: 0, legal: 0, environmental: 0 },
835:       dim,
836:       0.05,
837:     );
838:     const activeEvents = (updated.world as any).activeMacroEvents ?? [];
839:     const macroEvent = tryTriggerMacroEvent(newTension, activeEvents, finalSig.currentStage, now);
840:     const newActiveEvents = macroEvent ? [...activeEvents, macroEvent] : activeEvents;
841:     const updatedWorld = { ...updated.world, pestleTension: newTension, activeMacroEvents: newActiveEvents } as WorldState;
842: 
843:     return {
844:       updatedSig: finalSig,
845:       updatedWorld,
846:       finalResult,
847:       consequenceRecord: updatedRecord,
848:       narrativeSummary,
849:       feedback: evaluation.feedback,
850:       messages: this.messages,
851:     };
852:   }
