854:   /**
855:    * Select the best assessment task from the module based on encounter modality.
856:    */
857:   private selectTaskForModality(module: StageAssessment, modality: Modality): AssessmentTask {
858:     // Preferred task types for each modality, with fallback chains
859:     // If the preferred types aren't available in the module, we try broader types
860:     const modalityFallbackChain: Record<string, readonly TaskType[]> = {
861:       Deterministic: ['n_back', 'stroop', 'go_no_go', 'hold', 'reaction_time', 'rhythm'],
862:       LanguageReflective: ['llm_dialogue', 'self_report', 'emotion_identification', 'scenario'],
863:       ScenarioChoice: ['dilemma', 'scenario', 'emotion_identification', 'self_report'],
864:       Embodied: ['hold', 'rhythm', 'imitation', 'reaction_time', 'go_no_go'],
865:       Strategic: ['pattern_prediction', 'value_ranking', 'n_back', 'stroop'],
866:       SocialCooperative: ['cooperation', 'dilemma', 'emotion_identification', 'scenario', 'self_report'],
867:       ImmersiveRPG: ['scenario', 'dilemma', 'llm_dialogue', 'emotion_identification', 'self_report'],
868:     };
869: 
870:     const chain = modalityFallbackChain[modality] ?? ['n_back', 'scenario', 'self_report'];
871: 
872:     // Walk the fallback chain: first match wins
873:     for (const prefType of chain) {
874:       const match = module.tasks.find(t => t.type === prefType);
875:       if (match) return match;
876:     }
877: 
878:     // CRITICAL FIX: When no task type matches the modality's preference chain,
879:     // generate a modality-appropriate generic task instead of falling to tasks[0].
880:     // This prevents Cognitive modules (which have only n_back/pattern/go_nogo) from
881:     // showing n-back when ScenarioChoice modality is requested.
882:     return this.generateModalityFallbackTask(modality, module);
883:   }
884: 
885:   /**
886:    * Generate a generic task appropriate for the modality when the module
887:    * doesn't have any of the preferred task types. This ensures ScenarioChoice
888:    * always shows a dilemma, ImmersiveRPG always shows a scenario, etc.
889:    */
890:   private generateModalityFallbackTask(modality: Modality, module: StageAssessment): AssessmentTask {
891:     const prefix = `${module.line.toLowerCase()}-${module.stage.toLowerCase()}`;
892:     // Inject stage into all generated task parameters so TaskRenderers can use it for difficulty scaling
893:     const stage = module.stage;
894:     switch (modality) {
895:       case 'ScenarioChoice':
896:       case 'ImmersiveRPG':
897:         return {
898:           id: `generic-dilemma-${prefix}`,
899:           type: 'dilemma',
900:           description: `A developmental dilemma at the ${module.stage} stage of ${module.line} development`,
901:           parameters: { dilemmaType: 'developmental', choices: 4, stage, line: module.line },
902:           measures: ['depth', 'coherence'],
903:         };
904:       case 'LanguageReflective':
905:         return {
906:           id: `generic-self-report-${prefix}`,
907:           type: 'self_report',
908:           description: `Self-inquiry reflection at the ${module.stage} stage of ${module.line} development`,
909:           parameters: { stage },
910:           measures: ['depth', 'metacognition'],
911:         };
