1: /**
2:  * TaskRenderers — translates assessment TaskTypes into CLI-compatible MCQ prompts
3:  * and evaluates responses into TrialResult objects with real timing/accuracy data.
4:  *
5:  * Each renderer produces an AskUserQuestionParams-compatible prompt and a
6:  * response evaluator that generates TrialResult[] for the scoring engine.
7:  *
8:  * Key design:
9:  * - Options include drive/polarity metadata for differentiated scoring
10:  * - Correct answer position is shuffled to prevent gaming
11:  * - Each option maps to a specific drive expression
12:  */
13: import type { AssessmentTask, TrialResult } from '../types.js';
14: import type { AskUserQuestionParams } from '../agentTypes.js';
15: 
16: // ── ANSI helpers (must be at top for const hoisting) ──────────────────
17: 
18: const C = {
19:   reset: '\x1b[0m', bold: '\x1b[1m', dim: '\x1b[2m',
20:   green: '\x1b[32m', yellow: '\x1b[33m', blue: '\x1b[34m',
21:   magenta: '\x1b[35m', cyan: '\x1b[36m', red: '\x1b[31m',
22: };
23: 
24: // ── Option type with drive metadata ───────────────────────────────────
25: 
26: interface DriveOption {
27:   label: string;
28:   description: string;
29:   drive: 'agency' | 'communion' | 'eros' | 'agape';
30:   polarity: 'sto' | 'sts' | 'neutral';
31:   /** Score multiplier for correctness (1.0 = correct, 0.5 = partial, 0.0 = wrong) */
32:   correctnessScore: number;
33: }
34: 
35: /**
36:  * Shuffle an array in place (Fisher-Yates). Returns the same array.
37:  */
38: function shuffle<T>(arr: T[]): T[] {
39:   for (let i = arr.length - 1; i > 0; i--) {
40:     const j = Math.floor(Math.random() * (i + 1));
41:     [arr[i], arr[j]] = [arr[j]!, arr[i]!];
42:   }
43:   return arr;
44: }
45: 
46: // ── Symbol sets for cognitive tasks ────────────────────────────────────
47: 
48: const NBACK_SYMBOLS = ['◆', '●', '▲', '■', '★', '◇', '○', '△'];
49: const NBACK_SYMBOLS_EXTENDED = ['◆', '●', '▲', '■', '★', '◇', '○', '△', '◈', '◉', '◎', '✧'];
50: const STROOP_COLORS = [
51:   { word: 'RED', render: '\x1b[31mRED\x1b[0m', short: 'Red', initial: 'R' },
52:   { word: 'BLUE', render: '\x1b[34mBLUE\x1b[0m', short: 'Blue', initial: 'B' },
53:   { word: 'GREEN', render: '\x1b[32mGREEN\x1b[0m', short: 'Green', initial: 'G' },
54:   { word: 'YELLOW', render: '\x1b[33mYELLOW\x1b[0m', short: 'Yellow', initial: 'Y' },
55: ];
56: const STROOP_COLORS_EXTENDED = [
57:   ...STROOP_COLORS,
58:   { word: 'PURPLE', render: '\x1b[35mPURPLE\x1b[0m', short: 'Purple', initial: 'P' },
59:   { word: 'ORANGE', render: '\x1b[38;5;208mORANGE\x1b[0m', short: 'Orange', initial: 'O' },
60: ];
61: const GONOGO_STIMULI = ['⚔', '🛡', '☠', '✦'];
62: const GONOGO_STIMULI_EXTENDED = ['⚔', '🛡', '☠', '✦', '🔮', '💀'];
63: 
64: /**
65:  * Stage-specific difficulty parameters.
66:  * Lower stages = simpler tasks, fewer trials, larger symbol pools.
67:  * Higher stages = more complex tasks, more trials, abstract symbols.
68:  */
69: const STAGE_DIFFICULTY: Record<string, {
70:   nBackN: number; nBackTrials: number; stroopTrials: number;
71:   goNoGoTrials: number; holdItems: number; holdDurationMs: number;
72:   patternDisks: number; patternAttempts: number;
73:   symbolPool: readonly string[]; stroopColors: typeof STROOP_COLORS;
74:   goStimuli: readonly string[];
75: }> = {
76:   Infrared: { nBackN: 1, nBackTrials: 6, stroopTrials: 4, goNoGoTrials: 8, holdItems: 2, holdDurationMs: 3000, patternDisks: 2, patternAttempts: 3, symbolPool: NBACK_SYMBOLS.slice(0, 4), stroopColors: STROOP_COLORS.slice(0, 3), goStimuli: GONOGO_STIMULI.slice(0, 2) },
