78:   Red: { nBackN: 2, nBackTrials: 10, stroopTrials: 8, goNoGoTrials: 14, holdItems: 3, holdDurationMs: 5000, patternDisks: 3, patternAttempts: 4, symbolPool: NBACK_SYMBOLS, stroopColors: STROOP_COLORS, goStimuli: GONOGO_STIMULI },
79:   Amber: { nBackN: 2, nBackTrials: 12, stroopTrials: 10, goNoGoTrials: 16, holdItems: 3, holdDurationMs: 6000, patternDisks: 3, patternAttempts: 4, symbolPool: NBACK_SYMBOLS, stroopColors: STROOP_COLORS, goStimuli: GONOGO_STIMULI },
