82:   Turquoise: { nBackN: 3, nBackTrials: 18, stroopTrials: 14, goNoGoTrials: 22, holdItems: 5, holdDurationMs: 9000, patternDisks: 5, patternAttempts: 6, symbolPool: NBACK_SYMBOLS_EXTENDED, stroopColors: STROOP_COLORS_EXTENDED, goStimuli: GONOGO_STIMULI_EXTENDED },
