84: };
85: 
86: /** Get difficulty params for a stage, defaulting to Red */
87: function getDifficulty(stage?: string): typeof STAGE_DIFFICULTY['Red'] {
88:   return STAGE_DIFFICULTY[stage ?? 'Red'] ?? STAGE_DIFFICULTY['Red']!;
89: }
90: 
91: // ── Task type display names ────────────────────────────────────────────
92: 
93: export const TASK_TYPE_LABELS: Record<string, string> = {
94:   n_back: 'Working Memory',
95:   stroop: 'Inhibitory Control',
96:   go_no_go: 'Impulse Regulation',
97:   hold: 'Attentional Hold',
98:   pattern_prediction: 'Pattern Recognition',
99:   emotion_identification: 'Emotional Literacy',
100:   dilemma: 'Moral Reasoning',
101:   scenario: 'Situational Judgment',
102:   value_ranking: 'Value Prioritization',
103:   self_report: 'Self-Inquiry',
104:   reaction_time: 'Reaction Speed',
105:   rhythm: 'Rhythmic Attunement',
106:   imitation: 'Imitative Learning',
107:   cooperation: 'Cooperative Dynamics',
108:   llm_dialogue: 'Reflective Dialogue',
109: };
110: 
111: // ── N-Back Renderer ───────────────────────────────────────────────────
112: 
113: /**
114:  * Render an n-back task: generate a symbol sequence and ask the player
115:  * to identify which positions match the item from n steps back.
116:  */
117: export function renderNBack(task: AssessmentTask): {
118:   prompt: AskUserQuestionParams;
119:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
120: } {
121:   const diff = getDifficulty(task.parameters.stage as string | undefined);
122:   const n = (task.parameters.n as number) ?? diff.nBackN;
123:   const trialCount = (task.parameters.trials as number) ?? diff.nBackTrials;
124:   const symbols = diff.symbolPool;
125: 
126:   // Generate a sequence with guaranteed matches
127:   const sequence: string[] = [];
128:   const matchPositions: number[] = [];
129: 
130:   for (let i = 0; i < trialCount; i++) {
131:     if (i >= n && Math.random() < 0.4) {
132:       sequence.push(sequence[i - n]!);
133:       matchPositions.push(i);
134:     } else {
135:       const sym = symbols[Math.floor(Math.random() * symbols.length)]!;
136:       if (i >= n && sym === sequence[i - n]) {
137:         const alternatives = symbols.filter(s => s !== sequence[i - n]);
138:         sequence.push(alternatives[Math.floor(Math.random() * alternatives.length)]!);
139:       } else {
140:         sequence.push(sym);
141:       }
142:     }
143:   }
144: 
145:   const expectedCount = matchPositions.length;
146: 
147:   const displaySequence = sequence.map((s, i) => `${C.dim}[${i + 1}]${C.reset} ${s}`).join('  ');
148: 
149:   const question = [
150:     `You see a sequence of symbols. Track each one — does it match the symbol from ${n} steps back?`,
151:     ``,
152:     `${displaySequence}`,
153:     ``,
154:     `${C.bold}How many matches did you find?${C.reset}`,
155:   ].join('\n');
156: 
157:   // Build options with drive metadata, then shuffle
158:   const options: DriveOption[] = [
159:     { label: `${expectedCount} matches`, description: `I counted ${expectedCount} matches`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
160:     { label: `${Math.max(0, expectedCount - 1)} matches`, description: 'I may have missed one', drive: 'communion', polarity: 'neutral', correctnessScore: 0.7 },
161:     { label: `${expectedCount + 1} matches`, description: 'I may have counted an extra', drive: 'eros', polarity: 'neutral', correctnessScore: 0.5 },
162:     { label: `0 matches`, description: 'I found no matching pairs', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
163:   ];
164:   shuffle(options);
165: 
166:   return {
167:     prompt: {
168:       questions: [{
169:         question,
170:         header: 'Working Memory',
171:         options: options.map(o => ({ label: o.label, description: o.description })),
172:         allowWriteIn: true,
173:         multiSelect: false,
174:       }],
175:     },
176:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
177:       const durationMs = endTimeMs - startTimeMs;
178:       const numericMatch = answer.match(/\d+/);
179:       const playerCount = numericMatch ? parseInt(numericMatch[0]!, 10) : -1;
180: 
181:       const error = Math.abs(playerCount - expectedCount);
182:       const accuracy = Math.max(0, 1 - error / Math.max(1, trialCount * 0.5));
183: 
184:       const expectedTime = trialCount * ((task.parameters.stimulusDurationMs as number) ?? 1100) + 2000;
185:       const timeRatio = durationMs / expectedTime;
186:       const responseTime = timeRatio < 0.5 ? 0.9 : timeRatio < 1.5 ? 0.7 : timeRatio < 3 ? 0.5 : 0.3;
187:       const consistency = error === 0 ? 0.95 : error === 1 ? 0.7 : 0.4;
188: 
189:       // Match selected option to its drive metadata
190:       const matchedOpt = options.find(o => answer.toLowerCase().includes(o.label.toLowerCase().split(' ')[0]!));
191: 
192:       return {
193:         taskId: task.id,
194:         timestamp: startTimeMs,
195:         dimensions: { accuracy, response_time: responseTime, consistency },
196:         rawResponse: {
197:           playerCount, expectedCount, sequence: sequence.join(''), matchPositions,
198:           matchedDrive: matchedOpt?.drive ?? null,
199:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
200:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
201:         },
202:         durationMs,
203:       };
204:     },
205:   };
206: }
