310: /**
311:  * Render a Go/No-Go task: show stimuli and ask the player to count
312:  * how many "Go" (⚔) stimuli appeared vs "No-Go" (🛡) stimuli.
313:  */
314: export function renderGoNoGo(task: AssessmentTask): {
315:   prompt: AskUserQuestionParams;
316:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
317: } {
318:   const diff = getDifficulty(task.parameters.stage as string | undefined);
319:   const goRatio = (task.parameters.goRatio as number) ?? 0.7;
320:   const trialCount = (task.parameters.trials as number) ?? diff.goNoGoTrials;
321:   const stimuliPool = diff.goStimuli;
322: 
323:   const stimuli: string[] = [];
324:   let goCount = 0;
325:   let nogoCount = 0;
326:   for (let i = 0; i < trialCount; i++) {
327:     const isGo = Math.random() < goRatio;
328:     stimuli.push(isGo ? stimuliPool[0]! : stimuliPool[1]!);
329:     if (isGo) goCount++;
330:     else nogoCount++;
331:   }
332: 
333:   const display = stimuli.map((s, i) => `${C.dim}${i + 1}:${C.reset}${s}`).join(' ');
334: 
335:   const question = [
336:     `⚔ = GO (respond)   🛡 = NO-GO (withhold)`,
337:     ``,
338:     `${display}`,
339:     ``,
340:     `${C.bold}How many GO stimuli (⚔) were there?${C.reset}`,
341:   ].join('\n');
342: 
343:   const options: DriveOption[] = [
344:     { label: `${goCount} GO`, description: `I counted ${goCount} go signals`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
345:     { label: `${Math.max(0, goCount - 1)} GO`, description: 'I may have missed one', drive: 'communion', polarity: 'neutral', correctnessScore: 0.7 },
346:     { label: `${goCount + 1} GO`, description: 'I may have counted an extra', drive: 'eros', polarity: 'neutral', correctnessScore: 0.5 },
347:     { label: `I lost count`, description: 'Too many stimuli to track', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
348:   ];
349:   shuffle(options);
350: 
351:   return {
352:     prompt: {
353:       questions: [{
354:         question,
355:         header: 'Impulse Regulation',
356:         options: options.map(o => ({ label: o.label, description: o.description })),
357:         allowWriteIn: true,
358:         multiSelect: false,
359:       }],
360:     },
361:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
362:       const durationMs = endTimeMs - startTimeMs;
363:       const numericMatch = answer.match(/\d+/);
364:       const playerCount = numericMatch ? parseInt(numericMatch[0]!, 10) : -1;
365: 
366:       const error = Math.abs(playerCount - goCount);
367:       const accuracy = Math.max(0, 1 - error / Math.max(1, trialCount * 0.3));
368: 
369:       const expectedTime = trialCount * ((task.parameters.stimulusDurationMs as number) ?? 500) + 2000;
370:       const timeRatio = durationMs / expectedTime;
371:       const responseTime = timeRatio < 0.5 ? 0.9 : timeRatio < 1.5 ? 0.7 : timeRatio < 3 ? 0.5 : 0.3;
372: 
373:       const matchedOpt = options.find(o => answer.includes(o.label.split(' ')[0]!));
374: 
375:       return {
376:         taskId: task.id,
377:         timestamp: startTimeMs,
378:         dimensions: {
379:           accuracy,
380:           response_time: responseTime,
381:           consistency: error === 0 ? 0.95 : error === 1 ? 0.7 : 0.4,
382:         },
383:         rawResponse: {
384:           playerCount, goCount, nogoCount, stimuli: stimuli.join(''),
385:           matchedDrive: matchedOpt?.drive ?? null,
386:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
387:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
388:         },
389:         durationMs,
390:       };
391:     },
392:   };
393: }
