556:   const scenario = scenarios[Math.floor(Math.random() * scenarios.length)]!;
557:   const correctOpt: DriveOption = { label: scenario.emotion, description: 'Identify this emotion', drive: 'eros', polarity: 'neutral', correctnessScore: 1.0 };
558:   const wrongOpts: DriveOption[] = scenario.wrong.map((w, i) => ({
559:     label: w,
560:     description: 'A different emotional state',
561:     drive: i === 0 ? 'agency' : i === 1 ? 'communion' : 'agape',
562:     polarity: 'neutral',
563:     correctnessScore: 0.2,
564:   }));
565:   const options = shuffle([correctOpt, ...wrongOpts]);
566: 
567:   const question = [
568:     `Read this scenario and identify the PRIMARY emotion:`,
