75:     activeBeatId: null,
76:     completedBeatIds: [],
77:     factions: [],
78:     npcRelationships: [],
79:     pestleTension: { political: 0, economic: 0, social: 0, technological: 0, legal: 0, environmental: 0 },
80:     activeMacroEvents: [],
81:   };
82: }
83: 
84: /** All 7 modalities available in the system. */
85: const ALL_MODALITIES: Modality[] = [
86:   'Deterministic', 'Strategic', 'Embodied',
87:   'ScenarioChoice', 'LanguageReflective', 'SocialCooperative', 'ImmersiveRPG',
88: ];
89: 
90: 
91: 
92: /** Modalities that require specific session conditions. */
93: const ENERGY_GATED: Modality[] = ['Embodied'];
94: const TIME_GATED: Modality[] = ['Strategic'];
95: 
96: /**
97:  * Generate all eligible encounter candidates given current significator and world state.
98:  * Applies 5 filters: layer-perception, altitude, cooldown, narrative gate, modality availability.
99:  */
100: export function generateCandidates(
101:   sig: Significator,
102:   world: WorldState,
103:   now: number,
104:   session?: SessionContext,
105: ): EncounterCandidate[] {
106:   const maxStageOrd = stageOrdinal(sig.currentStage) + 1;
107:   const candidates: EncounterCandidate[] = [];
108:   const recent = world.recentEncounters ?? [];
109: 
110:   // Filter 5: Determine blocked modalities based on session context
111:   const blockedModalities = new Set<Modality>();
112:   if (session?.inferredEnergy === 'low') {
113:     ENERGY_GATED.forEach(m => blockedModalities.add(m));
114:   }
115:   if (session?.estimatedTimeAvailable !== undefined && session.estimatedTimeAvailable < 900000) {
116:     TIME_GATED.forEach(m => blockedModalities.add(m));
117:   }
118: 
119:   for (const holon of world.holons) {
120:     if (!holon.active) continue;
121: 
122:     // If forceLine is provided, filter candidates to only matching holon.line.
123:     if (session?.forceLine && holon.line !== session.forceLine) continue;
124: 
125:     // If forceStage is provided, filter candidates to only matching holon.stage.
126:     if (session?.forceStage && holon.stage !== session.forceStage) continue;
127: 
128:     const bypassChecks = !!(session?.forceLine || session?.forceStage);
129: 
130:     if (!bypassChecks) {
131:       // Filter 1: Layer-perception (stage <= current + 1)
132:       if (stageOrdinal(holon.stage) > maxStageOrd) continue;
133: 
134:       // Filter 2: Altitude requirement (stage <= line altitude + 1)
135:       const lineAltOrd = stageOrdinal(sig.altitudes[holon.line]);
136:       if (stageOrdinal(holon.stage) > lineAltOrd + 1) continue;
137:     }
138: 
139:     const moduleRef = `${holon.line}:${holon.stage}`;
140: 
